std::vector<std::vector<size_t>> waves(const MemoryTestSchedule &s){std::vector<std::vector<size_t>> out;for(const auto &w:s.waves){std::vector<size_t> row;for(const auto &e:w.entries)row.push_back(e.controller);out.push_back(std::move(row));}return out;}
std::string json(const MemoryTestScheduleReport &r){hier::protocol::JsonWriter w(true);writeMemoryTestSchedule(w,r);return w.str();}
